head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > removeCellImageSrc]<br/>Body Cell 정보를 사용하여 특정 Body Cell 의 imageSrc 속성값을 제거합니다.",
    "validation" : [
        "rowIndex(필수) 파라미터는 Body 가 MultiLine 일때 각 Line 의 Row 인덱스값은 같아야 합니다.",
        "columnInfo(필수) 파라미터는 Row 가 MultiLine 이어도 모든 Column 은 고유의 인덱스값을 가져야 합니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 파라미터 기본 선택값 설정 (정적 select1 은 초기 selectedIndex 미적용)
    par_rowIndex.setSelectedIndex(0);
    par_columnInfo.setSelectedIndex(1);

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  - Body 를 MultiLine 으로 구성 : gBody 에 <w2:row> 2개 -> 한 데이터 Row 가 2 Line 으로 표시
//  - Line1 : col1(인덱스 0, text) / col2(인덱스 1, textImage)
//  - Line2 : col3(인덱스 2, textImage) / col4(인덱스 3, text)
//    · gBody column 의 id 는 바인딩 DataList(dlt_bind) 의 컬럼 id 와 동일해야 데이터가 렌더됨
//    · Line2 의 첫 Column 인덱스가 0 이 아닌 2 로 이어짐 -> Column 인덱스는 Line 마다 초기화되지 않고 고유함
//    · 두 Line 모두 같은 데이터 Row 이므로 rowIndex 값은 동일함
//  - removeCellImageSrc 는 제거 메소드이므로 6개 textImage Cell 에 서로 다른 imageSrc 를 사전 설정
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Body 가 MultiLine(2 Line) 입니다. 한 데이터 Row 가 2 Line 에 걸쳐 표시되며 데이터 Row 는 3개(rowIndex 0~2) 입니다.\nLine1 : col1(columnInfo 0, text) / col2(columnInfo 1, textImage)\nLine2 : col3(columnInfo 2, textImage) / col4(columnInfo 3, text)\nTarget 생성 시 6개 textImage Cell 에 서로 다른 이미지를 미리 설정했습니다. (Row0 = ico_grid_add / ico_grid_del, Row1 = ico_grid_up / ico_grid_down, Row2 = gif.gif / png.png)\n[절차] rowIndex / columnInfo 를 선택하고 removeCellImageSrc 버튼을 클릭하세요. 같은 rowIndex 로 columnInfo 1(Line1) 과 columnInfo 2(Line2) 를 각각 호출해 보세요. 제거한 이미지는 Target 재생성 버튼으로 되돌릴 수 있습니다.\n[확인] 결과창의 제거 대상 Cell 위치(데이터 Row / Line / Line 내 순번) 와 제거 전후 이미지 경로, 그리고 그리드에서 아이콘이 사라진 위치를 비교하세요."', '', 'label1');

    // === 바인딩 DataList(dlt_bind) : col1~col4 ===
    $c.gcm.createBasicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { "col1": "서울 강남점", "col2": "수정", "col3": "삭제", "col4": "A등급" },
        { "col1": "부산 해운대점", "col2": "수정", "col3": "삭제", "col4": "B등급" },
        { "col1": "대구 수성점", "col2": "수정", "col3": "삭제", "col4": "C등급" }
    ]);

    // target 그리드 직접 구성 (Body MultiLine : gBody 에 <w2:row> 2개)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:560px;height:340px;">';
    strTarget += '<w2:caption style="" id="caption1" value="removeCellImageSrc MultiLine test grid"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="280" style="" inputType="text" id="hcol1" value="col1 (0, text)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol2" value="col2 (1, textImage)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="hrow2">';
    strTarget += '<w2:column width="280" style="" inputType="text" id="hcol3" value="col3 (2, textImage)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol4" value="col4 (3, text)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    // Line1 : 인덱스 0 / 1
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="280" style="" inputType="text" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="textImage" viewType="icon" id="col2" dataList="col2"></w2:column>';
    strTarget += '</w2:row>';
    // Line2 : 인덱스 2 / 3 (Line 이 바뀌어도 인덱스는 0 으로 초기화되지 않고 이어짐)
    strTarget += '<w2:row style="" id="brow2">';
    strTarget += '<w2:column width="280" style="" inputType="textImage" viewType="icon" id="col3" dataList="col3"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="col4" dataList="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 제거 대상값 사전 설정 : Row 별 / Line 별로 서로 다른 이미지를 지정하여 제거된 Cell 을 식별할 수 있게 함
    //  - columnInfo 1 = Line1 의 textImage, columnInfo 2 = Line2 의 textImage
    scwin.target1.setCellImageSrc(0, 1, "/cm/images/base/ico_grid_add.svg");
    scwin.target1.setCellImageSrc(0, 2, "/cm/images/base/ico_grid_del.svg");
    scwin.target1.setCellImageSrc(1, 1, "/cm/images/base/ico_grid_up.svg");
    scwin.target1.setCellImageSrc(1, 2, "/cm/images/base/ico_grid_down.svg");
    scwin.target1.setCellImageSrc(2, 1, "/img/gif.gif");
    scwin.target1.setCellImageSrc(2, 2, "/img/png.png");
}



// Cell 의 실제 표시 위치(데이터 Row / Line / Line 내 순번) 확인
scwin.getCellPos = function (rowIndex, colIndex) {
    let cellEl = document.querySelector("td[id$='_cell_" + rowIndex + "_" + colIndex + "']");
    if (!cellEl) {
        return "(Cell 없음)";
    }
    let tr = cellEl.parentElement;
    let trIdx = Array.prototype.indexOf.call(tr.parentElement.children, tr);
    let lineNo = (trIdx % 2) + 1;
    let dataRowNo = Math.floor(trIdx / 2);
    let colNoInLine = Array.prototype.indexOf.call(tr.children, cellEl) + 1;
    return "데이터 Row " + dataRowNo + " 의 Line " + lineNo + " / Line 내 " + colNoInLine + " 번째 Column";
}



scwin.btn_removeCellImageSrc_onclick = function () {
    let rowIndex = Number(par_rowIndex.getText());
    let columnInfo = Number(par_columnInfo.getText());

    // columnInfo 는 Line 을 넘어 고유한 인덱스이므로, 지정한 인덱스가 어느 Line 의 Cell 을 가리키는지와 함께 확인
    let before = target1.getCellImageSrc(rowIndex, columnInfo);
    let rtn = target1.removeCellImageSrc(rowIndex, columnInfo);
    let after = target1.getCellImageSrc(rowIndex, columnInfo);
    wf_body_bottom.getObj("scwin").setReturnValue("removeCellImageSrc(" + rowIndex + ", " + columnInfo + ") : " + rtn + " [제거 대상 Cell : " + scwin.getCellPos(rowIndex, columnInfo) + " / 제거 전 : " + before + " -> 제거 후 : " + after + "]");

    // 동일한 rowIndex 로 Line1 / Line2 Cell 의 현재 상태 확인 (MultiLine 이어도 두 Line 의 Row 인덱스는 같음)
    let line1 = target1.getCellImageSrc(rowIndex, 1);
    let line2 = target1.getCellImageSrc(rowIndex, 2);
    wf_body_bottom.getObj("scwin").setReturnValue("동일 rowIndex " + rowIndex + " 상태 -> Line1(columnInfo 1) : " + line1 + " / Line2(columnInfo 2) : " + line2);
}
